import * as THREE from 'three';

// All units: 1 = 10 cm (same as the picoCAD models).

// The CRT glass, as generated by tools/picocad/assets/computer.py (centre + size).
export const SCREEN = {
  center: new THREE.Vector3(8.0, 11.24, -0.97),
  width: 3.84,
  height: 2.88,
  px: { w: 1024, h: 768 },   // QuanOS internal resolution
};

const deg = THREE.MathUtils.degToRad;
const rad2deg = THREE.MathUtils.radToDeg;

/** Vertical fov that keeps a given horizontal fov on narrow screens. */
function vfovFor(aspect, baseV, minH) {
  const h = 2 * Math.atan(Math.tan(deg(baseV) / 2) * aspect);
  if (rad2deg(h) >= minH) return baseV;
  return Math.min(66, rad2deg(2 * Math.atan(Math.tan(deg(minH) / 2) / aspect)));
}

/** Main-menu camera: looking into the room, desk + CRT on the right. */
export function menuPose(aspect) {
  const portrait = aspect < 1;
  const fov = vfovFor(aspect, 40, portrait ? 62 : 66);
  return {
    pos: new THREE.Vector3(portrait ? 6 : -4, portrait ? 15 : 14.5, portrait ? 44 : 27),
    target: new THREE.Vector3(portrait ? 7 : 6.5, portrait ? 8.5 : 10.4, -7),
    fov,
  };
}

/** Close-up on the CRT (refs 2 & 3): bezel fills the view, sticky note on the right. */
export function screenPose(aspect) {
  const fov = 36;
  const t = Math.tan(deg(fov) / 2);
  const portrait = aspect < 1;
  // area to keep in view (units)
  const needW = portrait ? SCREEN.width * 1.04 : 5.5;
  const needH = portrait ? SCREEN.height * 1.1 : 3.6;
  const dist = Math.max(needH / 2 / t, needW / 2 / (t * aspect));
  const cx = SCREEN.center.x + (portrait ? 0 : 0.42);
  const cy = SCREEN.center.y - (portrait ? 0 : 0.05);
  return {
    pos: new THREE.Vector3(cx, cy + 0.08, SCREEN.center.z + dist),
    target: new THREE.Vector3(cx, cy, SCREEN.center.z),
    fov,
  };
}
